def separate_paren_groups(paren_string: str) -> List[str]:
    cleaned = ''.join(paren_string.split())
    groups = []
    balance = 0
    start = None
    for idx, ch in enumerate(cleaned):
        if ch == '(':
            if balance == 0:
                start = idx
            balance += 1
        elif ch == ')':
            balance -= 1
            if balance == 0 and start is not None:
                groups.append(cleaned[start:idx + 1])
                start = None
    return groups

