def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from math import inf
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # dp[i1][i2] - maximum sum when path1 is at (i1, j1) and path2 at (i2, j2),
    # where j1 = k - i1, j2 = k - i2, k = current step index (sum of coordinates)
    dp = [[-inf] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = grid[1][1]  # both start at (1,1), collect its value once

    for k in range(3, 2 * N + 1):
        new_dp = [[-inf] * (N + 1) for _ in range(N + 1)]
        for i1 in range(1, N + 1):
            j1 = k - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(1, N + 1):
                j2 = k - i2
                if j2 < 1 or j2 > N:
                    continue
                best = -inf
                for pi1 in (i1 - 1, i1):
                    if pi1 < 1:
                        continue
                    for pi2 in (i2 - 1, i2):
                        if pi2 < 1:
                            continue
                        best = max(best, dp[pi1][pi2])
                if best == -inf:
                    continue
                cell = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    cell += grid[i2][j2]
                new_dp[i1][i2] = best + cell
        dp = new_dp

    return dp[N][N] if dp[N][N] > -inf else 0

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Build grid indexing from 1 to N
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, v in grid_values:
        if x == 0 and y == 0 and v == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = v

    if N == 0:
        return 0

    # DP arrays: use -inf sentinel
    NEG_INF = -10 ** 18
    dp_prev = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    # Initial step: both walkers at (1,1)
    dp_prev[1][1] = grid[1][1]

    # Iterate over all possible step values (sum of coordinates)
    for step in range(3, 2 * N + 1):
        dp_cur = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        for i in range(1, N + 1):
            col1 = step - i
            if col1 < 1 or col1 > N:
                continue
            for j in range(1, N + 1):
                col2 = step - j
                if col2 < 1 or col2 > N:
                    continue

                val = grid[i][col1]
                if not (i == j and col1 == col2):
                    val += grid[j][col2]

                best = NEG_INF
                # Four possible previous positions
                # (i-1,j-1): both moved right
                if i > 1 and j > 1:
                    best = max(best, dp_prev[i - 1][j - 1])
                # (i-1,j): first moved right, second moved down
                if i > 1:
                    best = max(best, dp_prev[i - 1][j])
                # (i,j-1): first moved down, second moved right
                if j > 1:
                    best = max(best, dp_prev[i][j - 1])
                # (i,j): both moved down
                best = max(best, dp_prev[i][j])

                if best != NEG_INF:
                    dp_cur[i][j] = best + val
        dp_prev = dp_cur

    return dp_prev[N][N] if dp_prev[N][N] != NEG_INF else 0

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Build grid (1-indexed)
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for r, c, v in grid_values:
        if r == 0 and c == 0:
            break
        if 1 <= r <= N and 1 <= c <= N:
            grid[r][c] = v

    NEG_INF = -10**18
    # dp arrays
    prev = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    prev[1][1] = grid[1][1]

    max_step = 2 * (N - 1)
    for k in range(1, max_step + 1):
        sum_pos = k + 2  # row + col at current step
        next_dp = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        i_low = max(1, sum_pos - N)
        i_high = min(N, sum_pos - 1)
        for i1 in range(i_low, i_high + 1):
            j1 = sum_pos - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_low, i_high + 1):
                j2 = sum_pos - i2
                if j2 < 1 or j2 > N:
                    continue
                best = NEG_INF
                for di1 in (0, 1):
                    for di2 in (0, 1):
                        pi1 = i1 - di1
                        pi2 = i2 - di2
                        if pi1 < 1 or pi2 < 1:
                            continue
                        pj1 = (k + 1) - pi1
                        pj2 = (k + 1) - pi2
                        if pj1 < 1 or pj1 > N or pj2 < 1 or pj2 > N:
                            continue
                        cand = prev[pi1][pi2]
                        if cand == NEG_INF:
                            continue
                        val = grid[i1][j1]
                        if i1 != i2 or j1 != j2:
                            val += grid[i2][j2]
                        cand += val
                        if cand > best:
                            best = cand
                next_dp[i1][i2] = best
        prev = next_dp

    return prev[N][N] if N >= 1 else 0

def max_value_on_paths(N: int, grid_values: list[tuple[int, int, int]]) -> int:
    # Build the grid (1-indexed)
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    if N == 1:
        return grid[1][1]

    # dp[i1][i2] = max sum when robot1 at (i1, j1) and robot2 at (i2, j2),
    # where j1 = s + 2 - i1 and j2 = s + 2 - i2 for current step s = i1 + j1 - 2
    dp = [[-1] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = grid[1][1]

    # total steps from start to finish is 2*(N-1)
    for s in range(1, 2 * N - 1):  # 1 .. 2N-2 inclusive
        new_dp = [[-1] * (N + 1) for _ in range(N + 1)]
        for i1 in range(1, N + 1):
            j1 = s + 2 - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(1, N + 1):
                j2 = s + 2 - i2
                if j2 < 1 or j2 > N:
                    continue

                best = -1
                # predecessors: move right (0) or down (-1) for each robot
                for di1 in (0, -1):
                    for di2 in (0, -1):
                        pi1 = i1 - di1
                        pi2 = i2 - di2
                        if pi1 < 1 or pi1 > N or pi2 < 1 or pi2 > N:
                            continue
                        prev = dp[pi1][pi2]
                        if prev != -1 and prev > best:
                            best = prev
                if best == -1:
                    continue

                add = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    add += grid[i2][j2]
                new_dp[i1][i2] = best + add
        dp = new_dp

    return dp[N][N] if dp[N][N] != -1 else 0

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
