def find_number_combinations():
    results = []
    for d1 in range(1, 10):
        for d2 in range(1, 10):
            if d2 == d1:
                continue
            for d3 in range(1, 10):
                if d3 == d1 or d3 == d2:
                    continue
                n = d1 * 100 + d2 * 10 + d3
                m2 = 2 * n
                m3 = 3 * n
                if m2 >= 1000 or m3 >= 1000:
                    continue
                s2 = str(m2)
                s3 = str(m3)
                if '0' in s2 or '0' in s3:
                    continue
                if len(set(s2)) != 3 or len(set(s3)) != 3:
                    continue
                results.append((n, m2, m3))
    results.sort(key=lambda x: x[0])
    return results

def find_number_combinations():
    combinations = []
    # iterate over all 3‑digit numbers with digits 1‑9 and no repetition
    digits = range(1, 10)
    for d1 in digits:
        for d2 in digits:
            if d2 == d1:
                continue
            for d3 in digits:
                if d3 == d1 or d3 == d2:
                    continue
                n = d1 * 100 + d2 * 10 + d3
                m = 2 * n
                k = 3 * n
                # ensure m and k are 3‑digit numbers
                if m < 100 or m > 987 or k < 100 or k > 987:
                    continue
                # function to check digits of a number
                def valid(num):
                    s = str(num)
                    if len(s) != 3:
                        return False
                    seen = set()
                    for ch in s:
                        if ch == '0':
                            return False
                        if ch in seen:
                            return False
                        seen.add(ch)
                    return True
                if valid(m) and valid(k):
                    combinations.append((n, m, k))
    combinations.sort(key=lambda x: x[0])
    return combinations

