def max_product(num_str: str, N: int, K: int) -> int:
    n = N
    # dp[i][k] : maximum product for prefix num_str[:i] with k multiplication signs used
    dp = [[0] * (K + 1) for _ in range(n + 1)]
    # base case: no multiplication sign, whole prefix is one number
    for i in range(1, n + 1):
        dp[i][0] = int(num_str[:i])
    # DP transition
    for k in range(1, K + 1):
        # at least k+1 digits are needed to place k signs
        for i in range(k + 1, n + 1):
            best = 0
            for j in range(k, i):
                current_val = int(num_str[j:i])
                prod = dp[j][k - 1] * current_val
                if prod > best:
                    best = prod
            dp[i][k] = best
    return dp[n][K]

