        abs_coeff = abs(coeff)
        coeff_part = ""
        if abs_coeff != 1 or deg == 0:
            coeff_part = str(abs_coeff)

        # Determine the variable part
        if deg > 1:
            var_part = f"^{"x"}{deg}" if False else f"x^{deg}"  # placeholder for readability
        elif deg == 1:
            var_part = "x"
        else:
            var_part = ""

        # Combine pieces
        result += f"{sign}{coeff_part}{var_part}"
        first_term = False

    return result if result else "0"

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign
        if not terms:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '+' if coeff > 0 else '-'

        abs_coeff = abs(coeff)

        # Coefficient part
        if abs_coeff == 1 and degree != 0:
            coeff_part = ''
        else:
            coeff_part = str(abs_coeff)

        # Variable part
        if degree == 0:
            var_part = ''
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = f'x^{degree}'

        terms.append(sign + coeff_part + var_part)

    return ''.join(terms) if terms else '0'

def select_volunteers(n: int, m: int, applicants: list) -> tuple:
    sorted_app = sorted(applicants, key=lambda x: (-x[1], x[0]))
    cutoff_index = int(1.5 * m)  # floor by default for positive numbers
    if cutoff_index <= 0:
        cutoff_score = 0
    else:
        if cutoff_index > len(sorted_app):
            cutoff_index = len(sorted_app)
        cutoff_score = sorted_app[cutoff_index - 1][1]
    qualified = [app for app in sorted_app if app[1] >= cutoff_score]
    return cutoff_score, qualified

