    used_orig = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            if o in used_orig and used_orig[o] != e:
                return "Failed"
            mapping[e] = o
            used_orig[o] = e
    if len(mapping) < 26:
        return "Failed"
    decoded = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded.append(mapping[ch])
    return ''.join(decoded)

def largest_prime_factor(n: int) -> int:
    """Return the largest prime factor of the product of two distinct primes."""
    i = 2
    while i * i <= n:
        if n % i == 0:
            return n // i
        i += 1
    return n

def largest_prime_factor(n: int) -> int:
    """Return the larger of the two distinct prime factors of n.

    If n is prime (or no factor is found up to sqrt(n)), n itself is returned.
    """
    factor = 2
    while factor * factor <= n:
        if n % factor == 0:
            return n // factor
        if factor == 2:
            factor = 3
        else:
            factor += 2
    return n

def count_partitions(n: int, k: int, x: int) -> int:
    # Edge cases
    if k == 0:
        return 1 if n == 0 else 0
    if n < k * x:
        return 0
    if x <= 0:
        # If parts can be zero or negative, the count would be infinite.
        # Problem statement assumes x >= 1, so we simply return 0 here.
        return 0
    m = n - k * x  # shift to make each part >= 0
    # dp[i][j] = number of partitions of i into parts <= j
    dp = [[0] * (k + 1) for _ in range(m + 1)]
    for j in range(k + 1):
        dp[0][j] = 1  # empty partition
    for i in range(1, m + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i][j - 1]
            if i >= j:
                dp[i][j] += dp[i - j][j]
    return dp[m][k]

def count_partitions(n: int, k: int, x: int) -> int:
    # If the minimum possible sum exceeds n, no partitions exist.
    if k * x > n:
        return 0
    # Reduce each part by x to transform into a problem of non‑negative parts.
    remaining = n - k * x
    # dp[i][j] = number of partitions of i into exactly j positive parts
    dp = [[0] * (k + 1) for _ in range(remaining + 1)]
    dp[0][0] = 1
    for i in range(1, remaining + 1):
        for j in range(1, k + 1):
            # include partitions where the last part is 1
            dp[i][j] = dp[i - 1][j - 1]
            # or partitions where all parts are at least 1 (subtract 1 from each part)
            if i - j >= 0:
                dp[i][j] += dp[i - j][j]
    # Sum over all possible number of non-zero parts (0 to k)
    # dp[remaining][0] is non‑zero only when remaining == 0 (the empty partition)
    return sum(dp[remaining][:k + 1])

def count_partitions(n: int, k: int, x: int) -> int:
    """Return the number of partitions of n into exactly k parts, each >= x, ignoring order."""
    if k <= 0:
        return 1 if n == 0 else 0
    if n < k * x:
        return 0
    m = n - k * x
    # dp[i][j] = number of partitions of i into parts of size at most j
    # This equals number of partitions of i into at most j positive parts
    dp = [[0] * (k + 1) for _ in range(m + 1)]
    for j in range(k + 1):
        dp[0][j] = 1  # one way to partition 0
    for i in range(1, m + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i][j - 1]
            if i >= j:
                dp[i][j] += dp[i - j][j]
    return dp[m][k]

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]
    total = 1  # count the sequence containing only 'last'
    max_next = last // 2
    for nxt in range(1, max_next + 1):
        total += count_sequences(n, nxt, memo)
    memo[last] = total
    return total

def count_coprime_pairs(x0: int, y0: int) -> int:
    if x0 <= 0 or y0 <= 0 or y0 % x0 != 0:
        return 0
    k = y0 // x0
    ans = 0
    import math
    limit = int(math.isqrt(k))
    for a in range(1, limit + 1):
        if k % a == 0:
            b = k // a
            if math.gcd(a, b) == 1:
                if a == b:
                    ans += 1
                else:
                    ans += 2
    return ans

def count_coprime_pairs(x0: int, y0: int) -> int:
    """Counts pairs of positive integers (P, Q) with gcd(P, Q)=x0 and lcm(P, Q)=y0."""
    # Quick check: x0 must divide y0.
    if x0 == 0 or y0 % x0 != 0:
        return 0

    # Helper gcd function (Euclid's algorithm).
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    k = y0 // x0
    count = 0
    limit = int(k ** 0.5)
    for a in range(1, limit + 1):
        if k % a != 0:
            continue
        b = k // a
        if _gcd(a, b) == 1:
            if a == b:
                count += 1
            else:
                count += 2
    return count

