def preorder_traversal(inorder: str, postorder: str) -> str:
    idx_map = {c: i for i, c in enumerate(inorder)}

    def build(in_l: int, in_r: int, post_l: int, post_r: int) -> str:
        if in_l > in_r:
            return ''
        root = postorder[post_r]
        root_idx = idx_map[root]
        left_count = root_idx - in_l
        left = build(in_l, root_idx - 1, post_l, post_l + left_count - 1)
        right = build(root_idx + 1, in_r, post_l + left_count, post_r - 1)
        return root + left + right

    return build(0, len(inorder) - 1, 0, len(postorder) - 1)

def preorder_traversal(inorder: str, postorder: str) -> str:
    index_map = {char: i for i, char in enumerate(inorder)}

    def helper(in_l: int, in_r: int, post_l: int, post_r: int) -> str:
        if in_l >= in_r or post_l >= post_r:
            return ''
        root = postorder[post_r - 1]
        root_index = index_map[root]
        left_len = root_index - in_l
        left_pre = helper(in_l, root_index, post_l, post_l + left_len)
        right_pre = helper(root_index + 1, in_r, post_l + left_len, post_r - 1)
        return root + left_pre + right_pre

    return helper(0, len(inorder), 0, len(postorder))

def preorder_traversal(inorder: str, postorder: str) -> str:
