    def helper(in_start: int, in_end: int, post_start: int, post_end: int) -> str:
        if in_start > in_end:
            return ""
        root = postorder[post_end]
        in_root_idx = idx_map[root]
        left_size = in_root_idx - in_start
        left_pre = helper(in_start, in_root_idx - 1,
                          post_start, post_start + left_size - 1)
        right_pre = helper(in_root_idx + 1, in_end,
                           post_start + left_size, post_end - 1)
        return root + left_pre + right_pre

    if not inorder:
        return ""
    return helper(0, len(inorder) - 1, 0, len(postorder) - 1)

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ""
    # Map each character to its index in inorder for O(1) lookups
    idx_map = {ch: i for i, ch in enumerate(inorder)}

    def build_pre(in_start, in_end, post_start, post_end):
        if in_start > in_end or post_start > post_end:
            return ""
        root = postorder[post_end]
        root_index = idx_map[root]
        left_size = root_index - in_start
        # Build left subtree
        left_pre = build_pre(in_start, root_index - 1,
                             post_start, post_start + left_size - 1)
        # Build right subtree
        right_pre = build_pre(root_index + 1, in_end,
                              post_start + left_size, post_end - 1)
        return root + left_pre + right_pre

    return build_pre(0, len(inorder) - 1, 0, len(postorder) - 1)

