def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    if not areas or l <= 0:
        return max(0, l)
    # Clamp intervals to road bounds and discard empty ones
    intervals = []
    for start, end in areas:
        s = max(0, start)
        e = min(l, end)   # treat end as exclusive
        if e > s:
            intervals.append((s, e))
    if not intervals:
        return l
    # Sort intervals by start
    intervals.sort(key=lambda x: x[0])
    removed = 0
    curr_start, curr_end = intervals[0]
    for s, e in intervals[1:]:
        if s > curr_end:          # non-overlapping
            removed += curr_end - curr_start
            curr_start, curr_end = s, e
        else:                     # overlapping
            curr_end = max(curr_end, e)
    removed += curr_end - curr_start
    remaining = l - removed
    return max(0, remaining)

def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    if l <= 0 or not areas:
        return max(0, l)

    # Clip and sort intervals
    intervals = sorted(((max(0, a), min(l, b)) for a, b in areas if a < l and b > 0))
    if not intervals:
        return l

    merged_start, merged_end = intervals[0]
    covered = 0

    for start, end in intervals[1:]:
        if start <= merged_end:
            merged_end = max(merged_end, end)
        else:
            covered += merged_end - merged_start
            merged_start, merged_end = start, end
    covered += merged_end - merged_start

    remaining = l - covered
    return remaining if remaining >= 0 else 0

def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    if not areas:
        return l
    # Sort intervals by start coordinate
    areas.sort(key=lambda x: (x[0], x[1]))
    merged: List[Tuple[int, int]] = []
    for s, e in areas:
        # Ignore zero‑length or reversed intervals
        if s >= e:
            continue
        if not merged or s > merged[-1][1]:
            merged.append([s, e])
        else:
            merged[-1][1] = max(merged[-1][1], e)
    cleared_length = sum(end - start for start, end in merged)
    remaining = l - cleared_length
    return remaining if remaining >= 0 else 0

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    dp = [0] * (T + 1)
    for time, value in herbs:
        if time > T:
            continue
        for t in range(T, time - 1, -1):
            new_val = dp[t - time] + value
            if new_val > dp[t]:
                dp[t] = new_val
    return dp[T]

