def min_remaining_space(V: int, n: int, volumes: list[int]) -> int:
    reachable = [False] * (V + 1)
    reachable[0] = True
    for w in volumes:
        if w > V:
            continue
        for s in range(V, w - 1, -1):
            if reachable[s - w]:
                reachable[s] = True
    max_used = 0
    for s in range(V, -1, -1):
        if reachable[s]:
            max_used = s
            break
    return V - max_used

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Dynamic programming for subset sum
    can = [False] * (V + 1)
    can[0] = True
    for vol in volumes:
        if vol > V:
            continue
        # iterate backwards to avoid reusing the same item
        for s in range(V, vol - 1, -1):
            if can[s - vol]:
                can[s] = True
    # Find the largest achievable sum not exceeding V
    max_filled = max(i for i, possible in enumerate(can) if possible)
    return V - max_filled

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # DP array where dp[j] is True if volume j can be achieved
    dp = [False] * (V + 1)
    dp[0] = True
    for vol in volumes:
        if vol > V:
            continue
        for j in range(V, vol - 1, -1):
            if dp[j - vol]:
                dp[j] = True
    # Find the maximum achievable volume not exceeding V
    max_used = 0
    for j in range(V, -1, -1):
        if dp[j]:
            max_used = j
            break
    return V - max_used

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [0] * (m + 1)
    dp[0] = 1
    for max_cnt in a:
        prefix = [0] * (m + 1)
        prefix[0] = dp[0]
        for k in range(1, m + 1):
            prefix[k] = (prefix[k - 1] + dp[k]) % MOD
        new_dp = [0] * (m + 1)
        for k in range(m + 1):
            low = k - max_cnt - 1
            if low >= 0:
                new_dp[k] = (prefix[k] - prefix[low]) % MOD
            else:
                new_dp[k] = prefix[k] % MOD
        dp = new_dp
    return dp[m] % MOD

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    # If total possible pots less than required, no arrangements
    if sum(a) < m:
        return 0
    dp = [0] * (m + 1)
    dp[0] = 1
    for limit in a:
        new_dp = [0] * (m + 1)
        # prefix sums of dp
        prefix = [0] * (m + 1)
        prefix[0] = dp[0]
        for s in range(1, m + 1):
            prefix[s] = (prefix[s - 1] + dp[s]) % MOD
        for s in range(m + 1):
            low = s - limit - 1
            if low >= 0:
                val = prefix[s] - prefix[low]
            else:
                val = prefix[s]
            new_dp[s] = val % MOD
        dp = new_dp
    return dp[m] % MOD

def mod_inverse(a, b):
    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        g, s, t = extended_gcd(y, x % y)
        return g, t, s - (x // y) * t

    a_mod = a % b
    g, x, _ = extended_gcd(a_mod, b)
    if g != 1:
        return None
    return x % b

