        curr = inc[i] + dec[i] - 1
        if curr > max_len:
            max_len = curr
    return n - max_len

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    n = len(heights)
    if n <= 1:
        return 0

    # Longest Increasing Subsequence (LIS) ending at each index
    inc_len = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc_len[j] + 1 > inc_len[i]:
                inc_len[i] = inc_len[j] + 1

    # Longest Decreasing Subsequence (LDS) starting at each index
    dec_len = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(n - 1, i, -1):
            if heights[j] < heights[i] and dec_len[j] + 1 > dec_len[i]:
                dec_len[i] = dec_len[j] + 1

    # Longest bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        # peak at i counted twice, subtract 1
        bitonic_len = inc_len[i] + dec_len[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    return n - max_bitonic

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    n = len(heights)
    if n <= 1:
        return 0

    # LIS ending at each index (strictly increasing)
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # LDS starting at each index (strictly decreasing)
    lds = [1] * n
    for i in reversed(range(n)):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Max bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        # Subtract 1 to avoid double counting height[i]
        current = lis[i] + lds[i] - 1
        if current > max_bitonic:
            max_bitonic = current

    # Minimum students to leave
    return n - max_bitonic

