def min_groups(w, n, prices):
    prices.sort()
    i, j = 0, n - 1
    groups = 0
    while i <= j:
        if i == j:
            groups += 1
            break
        if prices[i] + prices[j] <= w:
            i += 1
            j -= 1
        else:
            j -= 1
        groups += 1
    return groups

def min_groups(w, n, prices):
    prices.sort()
    left, right = 0, len(prices) - 1
    groups = 0
    while left <= right:
        if left == right:
            groups += 1
            break
        if prices[left] + prices[right] <= w:
            left += 1
            right -= 1
        else:
            right -= 1
        groups += 1
    return groups

def total_smoked_cigarettes(n, k):
    if k <= 1:
        return n
    total = n
    butts = n
    while butts >= k:
        new = butts // k
        total += new
        butts = butts % k + new
    return total

def total_smoked_cigarettes(n, k):
    if n <= 0 or k <= 1:
        return n
    total = n
    butts = n
    while butts >= k:
        new_cigarettes = butts // k
        total += new_cigarettes
        butts = new_cigarettes + butts % k
    return total
